import{at as e,it as t,n,vt as r}from"./chunks/framework.CW63qgVu.js";var i=JSON.parse(`{"title":"Introduction","description":"Introduction to retroBITE, a self-hosted collection manager for retro games: how the project started, what it does and where to begin.","frontmatter":{"title":"Introduction","description":"Introduction to retroBITE, a self-hosted collection manager for retro games: how the project started, what it does and where to begin."},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md","lastUpdated":1791663075000}`),a={name:`docs/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>retroBITE is a self-hosted collection manager for retro games. It organizes ROMs, disc images and BIOS files by console, identifies every file against known titles, adds metadata and artwork, and serves the library over your local network straight to real hardware. It runs as a Docker Compose stack on your own server.</p><div class="info custom-block"><p class="custom-block-title">Public beta</p><p>retroBITE is in public beta. Expect rough edges and frequent updates, and report issues on <a href="https://github.com/retroBITE-app/retroBITE/issues" target="_blank" rel="noreferrer">GitHub</a> or <a href="https://discord.gg/EHJAkvJmpu" target="_blank" rel="noreferrer">Discord</a>. The <a href="/roadmap">roadmap</a> tracks what has shipped and what is planned next.</p></div><h2 id="how-it-started" tabindex="-1">How it started <a class="header-anchor" href="#how-it-started" aria-label="Permalink to “How it started”">​</a></h2><p>retroBITE was born out of necessity. What started as a hunt for a Docker setup to network-load games onto personal consoles quickly grew when the available projects fell short. A simple server script evolved into a full collection management hub.</p><p>Along the way, two veteran developers from different corners of the retro community joined forces. One needed a reliable way to serve games to real consoles over the network. The other needed a proper home for a growing collection, with every file identified, described and easy to find. Instead of building two tools, they built one: retroBITE.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><ul><li><strong>Console library</strong>: choose from a catalog of 130+ systems and give each console its own folder. Only the consoles you own appear in your library.</li><li><strong><a href="./guide/library-scanning">Library scanning</a></strong>: each console folder is scanned for the file types and BIOS files that system uses, with game counts and identification progress per console.</li><li><strong>File identification</strong>: files are matched by name and size, then by CRC32, MD5 and SHA1 checksums. Multi-disc games merge through cue sheets and <code>.m3u</code> playlists, and anything unmatched waits in <em>Needs identifying</em> with a best guess and a confidence score.</li><li><strong>Metadata and artwork</strong>: developer, publisher, genre, players and up to 23 artwork types from ScreenScraper, with Libretro thumbnails as a fallback.</li><li><strong>retroBITE score</strong>: a score out of 100 for each game, from LaunchBox community ratings and how many play it on RetroAchievements, with a rank across your library.</li><li><strong>RetroAchievements</strong>: link your account to see each game&#39;s achievement set, with hardcore and softcore progress synced automatically.</li><li><strong>Loader-ready layouts</strong>: per-console folder structures for Open PS2 Loader, RetroArch or one folder per game, plus a toolbox that writes loader configs, artwork and <code>.m3u</code> playlists.</li><li><strong>Network shares</strong>: Samba (SMBv1 to SMB3) and FTP serve the library directly to modded consoles and loaders, and <a href="./getting-started/configuration#ps3netsrv">ps3netsrv</a> streams PS3, PS2 and PS1 games to webMAN MOD.</li><li><strong><a href="./guide/conversion">Conversion</a> and transfer</strong>: convert disc images between CHD, CSO, RVZ, WBFS and other formats, and copy games to a USB drive, an SD card or a network share.</li><li><strong>Hardware docs</strong>: keep repair logs, calibration procedures and compatibility matrices in Markdown, filed by console, with revision history.</li></ul><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to “Where to start”">​</a></h2><p>Start with <a href="./getting-started/installation">Installation</a> to set up the Docker Compose stack, then read <a href="./guide/library-scanning">Library scanning</a> to see how retroBITE expects your files to be laid out on disk.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};